  // Normaliza: minúsculas, sin acentos ni puntos, espacios colapsados.
  function norm(s){
    return (s || '').toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/\./g, '')
      .replace(/[^a-z0-9\s]/g, ' ')
      .replace(/\s+/g, ' ').trim();
  }

  // Índice de tokens de arranque de palabra para acelerar/priorizar.
  var STREETS = DB.streets, CUADS = DB.cuads, TYPES = DB.types;

  // Puntaje de coincidencia (mayor = mejor): prefijo total > inicio de
  // palabra > subcadena. -1 = no coincide.
  function score(nombreNorm, q){
    if (nombreNorm === q) return 100;
    if (nombreNorm.indexOf(q) === 0) return 90;
    var idx = nombreNorm.indexOf(q);
    if (idx < 0) return -1;
    // ¿empieza en frontera de palabra?
    return nombreNorm.charAt(idx - 1) === ' ' ? 70 : 40;
  }

  // Busca calles y expande cada una en TODAS sus ubicaciones (cuadrantes).
  function buscarCalles(query, maxCalles){
    var q = norm(query);
    if (q.length < 2) return [];
    maxCalles = maxCalles || 8;

    var hits = [];
    for (var i = 0; i < STREETS.length; i++){
      var sc = score(STREETS[i][0], q);
      if (sc >= 0) hits.push([sc, STREETS[i][1].length, i]);
    }
    if (!hits.length) return [];
    // Ordena por puntaje desc, luego nombre más corto (más relevante) asc.
    hits.sort(function(a, b){ return b[0] - a[0] || a[1] - b[1]; });

    var out = [];
    for (var h = 0; h < hits.length && h < maxCalles; h++){
      var st = STREETS[hits[h][2]];
      var name = st[1], tipo = TYPES[st[2]] || 'Calle', flat = st[3];
      for (var k = 0; k < flat.length; k += 3){
        var cu = CUADS[flat[k]], lat = flat[k + 1], lng = flat[k + 2];
        var esNum = /^\d+$/.test(String(cu.n));
        out.push({
          comuna: cu.c,
          cuadN: cu.n,
          cod: cu.cod,
          cuadTxt: esNum ? ('Cuadrante N° ' + cu.n) : cu.s,
          sector: name + ' — ' + cu.s,
          street: name,
          tipo: tipo,
          tel: cu.tel,
          lat: lat,
          lng: lng
        });
      }
    }
    return out;
  }

  global.OS10_CALLES_DB = DB;
  global.OS10_buscarCalles = buscarCalles;
